+++ b/src/amr_dispatcher_core/include/amr_dispatcher_core/fleet/vda5050_order_builder.hpp
@@ -0,0 +1,50 @@
+#pragma once
+
+#include <cstdint>
+#include <optional>
+#include <string>
+#include <unordered_set>
+#include <vector>
+
+#include "amr_dispatcher_core/catalog/station_catalog.hpp"
+#include "amr_dispatcher_core/dispatcher/traffic_reservation.hpp"
+#include "amr_dispatcher_core/fleet/vehicle_adapter_interface.hpp"
+
+namespace amr_dispatcher_core::fleet {
+
+// Vda5050OrderBuilder 默认配置。
+struct Vda5050OrderBuilderConfig {
+  double default_max_speed_mps = 1.0;
+  std::string default_map_id = "map";
+};
+
+// 将调度选出的拓扑路径节点序列转换为标准 VehicleOrder（Spec §4.2 / §5）。
+//
+// 参数:
+//   - vehicle_id: 目标小车 ID
+//   - mission_id: 业务任务 ID（作为 order_id，保证整单可寻址）
+//   - order_update_id: 订单更新版本号
+//   - path_node_ids: Dijkstra 产出的节点 ID 序列（例如 ["station_A", "rn_1", "station_B"]）
+//   - catalog: 当前生效的路网拓扑目录（stations + road_nodes + 带 polyline 的 edges）
+//   - reserved_locks: 当前由 ResourceTable 成功上锁的资源集合（RouteNodeId / RouteEdgeId）
+//   - terminal_actions: 挂载在终点站点的动作（取货/卸货/充电等）
+//   - config: 默认速度与地图 ID 配置
+//
+// 放行规则:
+//   - 节点锁 RouteNodeId 存在 -> node.released = true（Base 区间），否则 false（Horizon 区间）
+//   - 边锁 RouteEdgeId 存在且两端节点均已放行 -> edge.released = true，否则 false
+//   - 协议一致性：一旦出现 released = false，其后所有节点与边一律拉平为 false
+//     （VDA 5050 规定 Horizon 区间之后不得再出现 Base 区间）
+//
+// 返回: 路径为空或任一节点在目录中缺失时返回 std::nullopt。
+std::optional<VehicleOrder> BuildVda5050OrderFromPath(
+    const std::string& vehicle_id,
+    const std::string& mission_id,
+    uint32_t order_update_id,
+    const std::vector<std::string>& path_node_ids,
+    const catalog::StationCatalog& catalog,
+    const std::unordered_set<std::string>& reserved_locks,
+    const std::vector<VehicleAction>& terminal_actions = {},
+    const Vda5050OrderBuilderConfig& config = {});
+
+}  // namespace amr_dispatcher_core::fleet
diff --git a/src/amr_dispatcher_core/src/fleet/vda5050_order_builder.cpp b/src/amr_dispatcher_core/src/fleet/vda5050_order_builder.cpp
new file mode 100644
index 0000000..c8fa7ce
--- /dev/null
+++ b/src/amr_dispatcher_core/src/fleet/vda5050_order_builder.cpp
@@ -0,0 +1,200 @@
+#include "amr_dispatcher_core/fleet/vda5050_order_builder.hpp"
+
+#include <algorithm>
+#include <cmath>
+
+namespace amr_dispatcher_core::fleet {
+namespace {
+
+// 在 stations 与 road_nodes 的混合 id 空间中查找节点坐标。
+// 未命中返回 nullptr（调用方据此判定非法路径）。
+const void* FindNodeCoords(const catalog::StationCatalog& catalog,
+                           const std::string& node_id,
+                           double* x,
+                           double* y,
+                           double* yaw) {
+  for (const auto& station : catalog.stations) {
+    if (station.id == node_id) {
+      *x = station.x;
+      *y = station.y;
+      *yaw = station.yaw;
+      return &station;
+    }
+  }
+  for (const auto& road_node : catalog.road_nodes) {
+    if (road_node.id == node_id) {
+      *x = road_node.x;
+      *y = road_node.y;
+      *yaw = road_node.yaw;
+      return &road_node;
+    }
+  }
+  return nullptr;
+}
+
+// 查找连接 start/end 的目录边：支持正向与双向边的反向行驶。
+// 返回 nullptr 表示目录中无此边（调用方走直线插值兜底）。
+const catalog::CatalogStationEdge* FindCatalogEdge(const catalog::StationCatalog& catalog,
+                                                   const std::string& start,
+                                                   const std::string& end,
+                                                   bool* traversed_backward) {
+  for (const auto& edge : catalog.edges) {
+    if (edge.from == start && edge.to == end) {
+      *traversed_backward = false;
+      return &edge;
+    }
+    if (edge.bidirectional && edge.to == start && edge.from == end) {
+      *traversed_backward = true;
+      return &edge;
+    }
+  }
+  return nullptr;
+}
+
+// 把 (x, y) 折线点转为带航向的轨迹点：每点航向取到下一点方向，末点沿用前段方向。
+std::vector<VehicleTrajectoryPoint> BuildTrajectory(
+    const std::vector<std::pair<double, double>>& points) {
+  std::vector<VehicleTrajectoryPoint> trajectory;
+  trajectory.reserve(points.size());
+  for (std::size_t i = 0; i < points.size(); ++i) {
+    VehicleTrajectoryPoint point;
+    point.x = points[i].first;
+    point.y = points[i].second;
+    if (points.size() == 1) {
+      point.yaw = 0.0;
+    } else if (i + 1 < points.size()) {
+      point.yaw = std::atan2(points[i + 1].second - points[i].second,
+                             points[i + 1].first - points[i].first);
+    } else {
+      point.yaw = trajectory.back().yaw;  // 末点沿用上一段航向
+    }
+    trajectory.push_back(point);
+  }
+  return trajectory;
+}
+
+// 边缺失或折线为空时的兜底：两端节点直线插值（首尾两点，带航向）。
+std::vector<VehicleTrajectoryPoint> BuildStraightLineFallback(double start_x,
+                                                             double start_y,
+                                                             double end_x,
+                                                             double end_y) {
+  std::vector<VehicleTrajectoryPoint> trajectory(2);
+  const double yaw = std::atan2(end_y - start_y, end_x - start_x);
+  trajectory[0].x = start_x;
+  trajectory[0].y = start_y;
+  trajectory[0].yaw = yaw;
+  trajectory[1].x = end_x;
+  trajectory[1].y = end_y;
+  trajectory[1].yaw = yaw;
+  return trajectory;
+}
+
+}  // namespace
+
+std::optional<VehicleOrder> BuildVda5050OrderFromPath(
+    const std::string& vehicle_id,
+    const std::string& mission_id,
+    const uint32_t order_update_id,
+    const std::vector<std::string>& path_node_ids,
+    const catalog::StationCatalog& catalog,
+    const std::unordered_set<std::string>& reserved_locks,
+    const std::vector<VehicleAction>& terminal_actions,
+    const Vda5050OrderBuilderConfig& config) {
+  if (path_node_ids.empty()) {
+    return std::nullopt;
+  }
+
+  const std::size_t node_count = path_node_ids.size();
+
+  // 1. 提取所有节点坐标；任一节点缺失即整单作废（防止小车驶向未定义坐标）。
+  std::vector<double> xs(node_count);
+  std::vector<double> ys(node_count);
+  std::vector<double> yaws(node_count);
+  for (std::size_t i = 0; i < node_count; ++i) {
+    if (FindNodeCoords(catalog, path_node_ids[i], &xs[i], &ys[i], &yaws[i]) == nullptr) {
+      return std::nullopt;
+    }
+  }
+
+  // 2. 原始放行判定（仅看锁，尚未做协议一致性拉平）。
+  const std::size_t edge_count = node_count - 1;
+  std::vector<bool> node_raw(node_count, false);
+  std::vector<bool> edge_raw(edge_count, false);
+  for (std::size_t i = 0; i < node_count; ++i) {
+    node_raw[i] = reserved_locks.count(dispatcher::ResourceTable::RouteNodeId(
+                      path_node_ids[i])) > 0;
+  }
+  for (std::size_t i = 0; i < edge_count; ++i) {
+    const auto edge_id = dispatcher::ResourceTable::RouteEdgeId(path_node_ids[i],
+                                                                path_node_ids[i + 1]);
+    // 边锁存在且两端节点均已获路权
+    edge_raw[i] = reserved_locks.count(edge_id) > 0 && node_raw[i] && node_raw[i + 1];
+  }
+
+  // 3. 协议一致性拉平：按 node0 -> edge0 -> node1 -> edge1 ... 的行驶顺序遍历，
+  //    一旦出现 released = false（Horizon 区间），其后所有节点与边一律为 false
+  //    （VDA 5050 规定 Horizon 之后不得再出现 Base 区间）。
+  std::vector<bool> node_released(node_count, false);
+  std::vector<bool> edge_released(edge_count, false);
+  bool horizon_started = false;
+  for (std::size_t i = 0; i < node_count; ++i) {
+    node_released[i] = !horizon_started && node_raw[i];
+    horizon_started = horizon_started || !node_released[i];
+    if (i + 1 < node_count) {
+      edge_released[i] = !horizon_started && edge_raw[i];
+      horizon_started = horizon_started || !edge_released[i];
+    }
+  }
+
+  // 4. 组装订单：sequence_id 取 VDA 5050 规范的偶数序列 0, 2, 4 ...
+  VehicleOrder order;
+  order.order_id = mission_id;
+  order.order_update_id = order_update_id;
+  order.vehicle_id = vehicle_id;
+  order.nodes.reserve(node_count);
+  order.edges.reserve(edge_count);
+
+  const std::size_t last_index = node_count - 1;
+  for (std::size_t i = 0; i < node_count; ++i) {
+    VehicleNode node;
+    node.node_id = path_node_ids[i];
+    node.sequence_id = static_cast<uint32_t>(i * 2);
+    node.x = xs[i];
+    node.y = ys[i];
+    node.yaw = yaws[i];
+    node.released = node_released[i];
+    if (i == last_index) {
+      node.actions = terminal_actions;  // 终点动作挂载
+    }
+    order.nodes.push_back(std::move(node));
+
+    if (i + 1 < node_count) {
+      VehicleEdge edge;
+      edge.start_node_id = path_node_ids[i];
+      edge.end_node_id = path_node_ids[i + 1];
+      edge.edge_id = dispatcher::ResourceTable::RouteEdgeId(edge.start_node_id,
+                                                            edge.end_node_id);
+      edge.released = edge_released[i];
+      edge.max_speed = config.default_max_speed_mps;
+
+      bool traversed_backward = false;
+      const auto* catalog_edge =
+          FindCatalogEdge(catalog, edge.start_node_id, edge.end_node_id, &traversed_backward);
+      if (catalog_edge != nullptr && !catalog_edge->polyline.empty()) {
+        auto points = catalog_edge->polyline;
+        if (traversed_backward) {
+          std::reverse(points.begin(), points.end());  // 反向行驶：折线按行驶方向反转
+        }
+        edge.polyline = BuildTrajectory(points);
+      } else {
+        edge.polyline = BuildStraightLineFallback(xs[i], ys[i], xs[i + 1], ys[i + 1]);
+      }
+
+      order.edges.push_back(std::move(edge));
+    }
+  }
+
+  return order;
+}
+
+}  // namespace amr_dispatcher_core::fleet
diff --git a/test/unit/test_vda5050_order_builder.cpp b/test/unit/test_vda5050_order_builder.cpp
new file mode 100644
index 0000000..b15c05f
--- /dev/null
+++ b/test/unit/test_vda5050_order_builder.cpp
@@ -0,0 +1,239 @@
+#include "amr_dispatcher_core/fleet/vda5050_order_builder.hpp"
+
+#include <gtest/gtest.h>
+
+#include <cmath>
+#include <string>
+#include <unordered_set>
+#include <vector>
+
+#include "amr_dispatcher_core/catalog/station_catalog.hpp"
+#include "amr_dispatcher_core/dispatcher/traffic_reservation.hpp"
+
+namespace fleet = amr_dispatcher_core::fleet;
+namespace catalog_ns = amr_dispatcher_core::catalog;
+using amr_dispatcher_core::dispatcher::ResourceTable;
+
+namespace {
+
+// L 形拓扑：station_A(0,0) --弯折线--> rn_1(10,0) --竖直--> station_B(10,10)
+catalog_ns::StationCatalog MakeCatalog() {
+  catalog_ns::StationCatalog catalog;
+  catalog.stations.push_back({"station_A", "map", 0.0, 0.0, 0.0, "pickup"});
+  catalog.stations.push_back({"station_B", "map", 10.0, 10.0, 1.5707963, "dropoff"});
+  catalog.road_nodes.push_back({"rn_1", "map", 10.0, 0.0, 1.5707963});
+
+  catalog_ns::CatalogStationEdge to_corner;
+  to_corner.from = "station_A";
+  to_corner.to = "rn_1";
+  to_corner.distance_m = 10.0;
+  to_corner.bidirectional = true;
+  to_corner.enabled = true;
+  to_corner.polyline = {{0.0, 0.0}, {4.0, 0.0}, {7.0, 0.5}, {10.0, 0.0}};  // 真实弯曲折线
+  catalog.edges.push_back(to_corner);
+
+  catalog_ns::CatalogStationEdge to_dest;
+  to_dest.from = "rn_1";
+  to_dest.to = "station_B";
+  to_dest.distance_m = 10.0;
+  to_dest.bidirectional = true;
+  to_dest.enabled = true;
+  to_dest.polyline = {{10.0, 0.0}, {10.0, 5.0}, {10.0, 10.0}};
+  catalog.edges.push_back(to_dest);
+  return catalog;
+}
+
+std::vector<std::string> MakePath() { return {"station_A", "rn_1", "station_B"}; }
+
+std::unordered_set<std::string> LocksFor(const std::vector<std::string>& path) {
+  const auto lock_ids = ResourceTable::BuildLockIds(path, /*include_intersection_locks=*/true);
+  return std::unordered_set<std::string>(lock_ids.begin(), lock_ids.end());
+}
+
+}  // namespace
+
+TEST(Vda5050OrderBuilderTest, FullLockedPath_MarksAllReleasedAndAttachesTerminalAction) {
+  const auto catalog = MakeCatalog();
+  const auto path = MakePath();
+  const auto reserved = LocksFor(path);
+
+  fleet::VehicleAction action;
+  action.action_type = "drop";
+  action.action_id = "act_drop_1";
+  action.parameters = {{"station", "station_B"}};
+
+  auto order = fleet::BuildVda5050OrderFromPath(
+      "amr_01", "mission_42", /*order_update_id=*/5, path, catalog, reserved, {action});
+
+  ASSERT_TRUE(order.has_value());
+  EXPECT_EQ(order->vehicle_id, "amr_01");
+  EXPECT_EQ(order->order_id, "mission_42");
+  EXPECT_EQ(order->order_update_id, 5U);
+
+  ASSERT_EQ(order->nodes.size(), 3U);
+  ASSERT_EQ(order->edges.size(), 2U);
+
+  // 全锁场景：Base 区间贯通整单
+  for (const auto& node : order->nodes) {
+    EXPECT_TRUE(node.released) << node.node_id;
+  }
+  for (const auto& edge : order->edges) {
+    EXPECT_TRUE(edge.released) << edge.edge_id;
+  }
+
+  // VDA 5050 奇数 sequenceId 规范：0, 2, 4
+  EXPECT_EQ(order->nodes[0].sequence_id, 0U);
+  EXPECT_EQ(order->nodes[1].sequence_id, 2U);
+  EXPECT_EQ(order->nodes[2].sequence_id, 4U);
+
+  // 坐标从 stations / road_nodes 中提取
+  EXPECT_DOUBLE_EQ(order->nodes[0].x, 0.0);
+  EXPECT_DOUBLE_EQ(order->nodes[0].y, 0.0);
+  EXPECT_DOUBLE_EQ(order->nodes[1].x, 10.0);
+  EXPECT_DOUBLE_EQ(order->nodes[1].y, 0.0);
+  EXPECT_DOUBLE_EQ(order->nodes[2].x, 10.0);
+  EXPECT_DOUBLE_EQ(order->nodes[2].y, 10.0);
+  EXPECT_DOUBLE_EQ(order->nodes[2].yaw, 1.5707963);
+
+  // 终点动作挂载在最后一个节点，前序节点不挂动作
+  EXPECT_TRUE(order->nodes[0].actions.empty());
+  EXPECT_TRUE(order->nodes[1].actions.empty());
+  ASSERT_EQ(order->nodes[2].actions.size(), 1U);
+  EXPECT_EQ(order->nodes[2].actions[0].action_type, "drop");
+  EXPECT_EQ(order->nodes[2].actions[0].action_id, "act_drop_1");
+
+  // 边字段按 ResourceTable 命名规则生成
+  EXPECT_EQ(order->edges[0].start_node_id, "station_A");
+  EXPECT_EQ(order->edges[0].end_node_id, "rn_1");
+  EXPECT_EQ(order->edges[0].edge_id, ResourceTable::RouteEdgeId("station_A", "rn_1"));
+  EXPECT_EQ(order->edges[1].edge_id, ResourceTable::RouteEdgeId("rn_1", "station_B"));
+  EXPECT_EQ(order->edges[0].max_speed, 1.0);
+}
+
+TEST(Vda5050OrderBuilderTest, PartialLock_MarksBaseThenHorizonSegment) {
+  const auto catalog = MakeCatalog();
+  const auto path = MakePath();
+
+  // 三个节点锁全有，仅第一条边有锁（第二条边未获路权）
+  auto reserved = LocksFor(path);
+  reserved.erase(ResourceTable::RouteEdgeId("rn_1", "station_B"));
+
+  auto order = fleet::BuildVda5050OrderFromPath(
+      "amr_01", "mission_43", /*order_update_id=*/0, path, catalog, reserved);
+
+  ASSERT_TRUE(order.has_value());
+  ASSERT_EQ(order->nodes.size(), 3U);
+  ASSERT_EQ(order->edges.size(), 2U);
+
+  // 前两节点 + 第一条边属于 Base 区间
+  EXPECT_TRUE(order->nodes[0].released);
+  EXPECT_TRUE(order->edges[0].released);
+  EXPECT_TRUE(order->nodes[1].released);
+
+  // 第二条边无锁 -> Horizon；其后的节点即使持有节点锁也必须被拉平为 false
+  EXPECT_FALSE(order->edges[1].released);
+  EXPECT_FALSE(order->nodes[2].released);
+}
+
+TEST(Vda5050OrderBuilderTest, CurvedPolyline_PreservedInOrderAndReversedWhenTraversingBackward) {
+  const auto catalog = MakeCatalog();
+
+  // 正向：A -> rn_1 -> B
+  const auto path = MakePath();
+  const auto reserved = LocksFor(path);
+  auto forward = fleet::BuildVda5050OrderFromPath(
+      "amr_01", "mission_44", 0, path, catalog, reserved);
+
+  ASSERT_TRUE(forward.has_value());
+  ASSERT_EQ(forward->edges[0].polyline.size(), 4U);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[0].x, 0.0);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[0].y, 0.0);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[1].x, 4.0);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[1].y, 0.0);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[2].x, 7.0);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[2].y, 0.5);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[3].x, 10.0);
+  EXPECT_DOUBLE_EQ(forward->edges[0].polyline[3].y, 0.0);
+
+  // yaw 取所在行驶方向：首段水平 -> 0，次段 atan2(0.5, 3)
+  EXPECT_NEAR(forward->edges[0].polyline[0].yaw, 0.0, 1e-9);
+  EXPECT_NEAR(forward->edges[0].polyline[1].yaw, std::atan2(0.5, 3.0), 1e-9);
+
+  ASSERT_EQ(forward->edges[1].polyline.size(), 3U);
+  EXPECT_NEAR(forward->edges[1].polyline[0].yaw, M_PI / 2.0, 1e-9);
+
+  // 反向：B -> rn_1 -> A，双向边折线需按行驶方向反转
+  const std::vector<std::string> reverse_path = {"station_B", "rn_1", "station_A"};
+  const auto reverse_locks = LocksFor(reverse_path);
+  auto reverse = fleet::BuildVda5050OrderFromPath(
+      "amr_01", "mission_45", 0, reverse_path, catalog, reverse_locks);
+
+  ASSERT_TRUE(reverse.has_value());
+  ASSERT_EQ(reverse->edges[0].polyline.size(), 3U);
+  EXPECT_DOUBLE_EQ(reverse->edges[0].polyline[0].x, 10.0);
+  EXPECT_DOUBLE_EQ(reverse->edges[0].polyline[0].y, 10.0);
+  EXPECT_DOUBLE_EQ(reverse->edges[0].polyline[2].x, 10.0);
+  EXPECT_DOUBLE_EQ(reverse->edges[0].polyline[2].y, 0.0);
+  EXPECT_NEAR(reverse->edges[0].polyline[0].yaw, -M_PI / 2.0, 1e-9);
+
+  ASSERT_EQ(reverse->edges[1].polyline.size(), 4U);
+  EXPECT_DOUBLE_EQ(reverse->edges[1].polyline[0].x, 10.0);
+  EXPECT_DOUBLE_EQ(reverse->edges[1].polyline[0].y, 0.0);
+  EXPECT_DOUBLE_EQ(reverse->edges[1].polyline[3].x, 0.0);
+  EXPECT_DOUBLE_EQ(reverse->edges[1].polyline[3].y, 0.0);
+}
+
+TEST(Vda5050OrderBuilderTest, MissingCatalogEdge_FallsBackToStraightLine) {
+  const auto catalog = MakeCatalog();
+  // A 与 B 之间无直连边：触发两端节点直线插值
