9	// 在 stations 与 road_nodes 的混合 id 空间中查找节点坐标。
10	// 未命中返回 nullptr（调用方据此判定非法路径）。
11	const void* FindNodeCoords(const catalog::StationCatalog& catalog,
12	                           const std::string& node_id,
13	                           double* x,
14	                           double* y,
15	                           double* yaw) {
16	  for (const auto& station : catalog.stations) {
17	    if (station.id == node_id) {
18	      *x = station.x;
19	      *y = station.y;
20	      *yaw = station.yaw;
21	      return &station;
22	    }
23	  }
24	  for (const auto& road_node : catalog.road_nodes) {
25	    if (road_node.id == node_id) {
26	      *x = road_node.x;
